package io.tornado.optimization;
import io.tornado.persistence.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
class ProfileSelectionServiceTest{
 @Test void fallbackIsReplacedButMarginalChallengerCannotFlipValidatedProfile(){var profiles=mock(StrategyHorizonProfileRepository.class);var settings=mock(AppSettingsRepository.class);AppSettings configuration=new AppSettings(900,900);configuration.updateProfileSelection(30,60,new BigDecimal("2"),new BigDecimal("0.1"),24);when(settings.findById(1)).thenReturn(Optional.of(configuration));var evidence=evidence(65,60);var challenger=new WalkForwardProfileSelector.CandidateEvaluation(new WalkForwardProfileSelector.Configuration("30m","14"),evidence,true,61,null,null);StrategyHorizonProfile current=StrategyHorizonProfile.selected(null,ProfileScope.GLOBAL,"ADX_14",2,14400,"1h","14",2,evidence(64,60),"current",Instant.now());when(profiles.findByActiveKey(anyString())).thenReturn(Optional.of(current));var result=new ProfileSelectionService(profiles,settings).apply(challenger,ProfileScope.GLOBAL,null,"ADX_14",2,14400);assertThat(result.changed()).isFalse();assertThat(result.reason()).contains("replacement threshold");verify(profiles,never()).save(any());}
 @Test void coinOverrideNeedsTheStricterSampleRequirement(){var profiles=mock(StrategyHorizonProfileRepository.class);var settings=mock(AppSettingsRepository.class);AppSettings configuration=new AppSettings(900,900);configuration.updateProfileSelection(30,100,new BigDecimal("2"),new BigDecimal("0.1"),24);when(settings.findById(1)).thenReturn(Optional.of(configuration));var evidence=new StrategyHorizonProfile.Evidence(120,80,40,60,60,50,50,60,.2,.2,5,2,4,3,75,70);var challenger=new WalkForwardProfileSelector.CandidateEvaluation(new WalkForwardProfileSelector.Configuration("15m","14"),evidence,true,70,null,null);Coin coin=new Coin("BTC","BTCUSDT");var result=new ProfileSelectionService(profiles,settings).apply(challenger,ProfileScope.COIN_SPECIFIC,coin,"RSI_14",2,3600);assertThat(result.changed()).isFalse();assertThat(result.reason()).contains("Insufficient");}
 private StrategyHorizonProfile.Evidence evidence(double directional,double score){return new StrategyHorizonProfile.Evidence(100,100,50,55,directional,45,50,55,.1,.1,5,2,4,3,75,score);}
}
